    narration: 'Translating Camera 2 changes the baseline T. The epipole and the red epipolar line move, changing the candidate locations for p\u2082.',
    rotationCamera2: 45,
    translationCamera2: 5
  }
];

function updateScene() {
  disposeGroup(dynamicGroup);

  const C2 = camera2Center();
  const n2 = camera2Normal();
  const b2 = makeBasisFromNormal(n2);
  const plane2Center = C2.clone().addScaledVector(n2, 2.30)
    .addScaledVector(b2.u, -0.05)
    .addScaledVector(b2.v, 0.04);

  const plane2 = addPlaneOutline(dynamicGroup, plane2Center, n2, 3.10, 3.64, BLACK, 0.029);
  addCamera(dynamicGroup, C2, plane2.corners, n2, -1);

  const e2 = projectFromCameraToPlane(C2, C1, plane2Center, n2);
  const p2 = projectFromCameraToPlane(C2, P, plane2Center, n2);
  const p1OnPlane2 = projectFromCameraToPlane(C2, p1, plane2Center, n2);
  const [lineA, lineB] = clipLineToPlaneRect(e2, p2, plane2Center, plane2.u, plane2.v, plane2.width, plane2.height);

  addDashedSegment(dynamicGroup, C1, C2, BLACK, 0.018, 0.26, 0.18);
  addDashedSegment(dynamicGroup, C2, P, BLACK, 0.018, 0.25, 0.17);
  addDashedSegment(dynamicGroup, C1, e2, BLACK, 0.016, 0.23, 0.17);
  addDashedSegment(dynamicGroup, P, p2, BLACK, 0.016, 0.23, 0.16);
  addDashedSegment(dynamicGroup, p1, p1OnPlane2, BLACK, 0.016, 0.23, 0.16);

  addCylinderBetween(dynamicGroup, lineA, lineB, 0.048, RED, 1, 24);

  const epipolarPlaneGeom = new THREE.BufferGeometry().setFromPoints([C1, C2, P]);
  epipolarPlaneGeom.setIndex([0, 1, 2]);
  const epipolarPlane = new THREE.Mesh(
    epipolarPlaneGeom,
    new THREE.MeshBasicMaterial({
      color: MAGENTA,
      transparent: true,
      opacity: 0.10,
      side: THREE.DoubleSide,
      depthWrite: false
    })
  );
  dynamicGroup.add(epipolarPlane);

  addPoint(dynamicGroup, e2, RED, 0.112);
  addPoint(dynamicGroup, p2, GREEN, 0.112);
  addPoint(dynamicGroup, p1OnPlane2, CYAN, 0.098);

  const origin2 = plane2Center.clone().addScaledVector(n2, 0.10);
  const x2Tip = addArrow(dynamicGroup, origin2, plane2.u.clone().multiplyScalar(-1), 1.12, BLUE, 0.019, 0.92);
  const y2Tip = addArrow(dynamicGroup, origin2, plane2.v, 1.16, BLUE, 0.019, 0.92);
  const z2Tip = addArrow(dynamicGroup, origin2, n2, 0.94, BLUE, 0.019, 0.92);

  const tStart = C1.clone().add(new THREE.Vector3(0.05, -0.58, 0.62));
  const tEnd = C2.clone().add(new THREE.Vector3(-0.05, -0.58, 0.62));
  addArrow(dynamicGroup, tStart, new THREE.Vector3().subVectors(tEnd, tStart), tStart.distanceTo(tEnd), GREEN, 0.026, 1.08);

  const curveStart = C1.clone().add(new THREE.Vector3(1.05, -1.05, 0.92));
  const curveEnd = C2.clone().add(new THREE.Vector3(-1.10, -1.05, 0.92));
  const curveControl = new THREE.Vector3((curveStart.x + curveEnd.x) * 0.5, -3.42, 1.22);
  addCurvedArrow(dynamicGroup, curveStart, curveControl, curveEnd, GREEN, 0.032);

  labels.camera2.pos.copy(C2).add(new THREE.Vector3(0.76, -0.45, -0.02));
  labels.image2.pos.copy(plane2.corners[2]).add(new THREE.Vector3(0.06, 0.23, 0.02));
