// input slab 256x256x3  → BoxGeometry(3.0, 3.0, 0.05)  front=image-ish, sides #7a2f18
// enc 256x256x128       → BoxGeometry(3.0, 3.0, 1.6)   orange #a34a2a
// enc 128x128x128       → BoxGeometry(1.6, 1.6, 1.6)
// enc 64x64x256         → BoxGeometry(0.9, 0.9, 3.2)
// enc 32x32x256         → BoxGeometry(0.5, 0.5, 3.2)
// enc 16x16x512         → BoxGeometry(0.28, 0.28, 6.0)  self-attention
// bottleneck 8x8x512    → BoxGeometry(0.15, 0.15, 6.0)
// decoder mirror: same sizes on right
// output slab           → BoxGeometry(3.0, 3.0, 0.05) noise texture
// skip arrows           → QuadraticBezierCurve3 → TubeGeometry + ConeGeometry head, #c96a3a
// residual arrows       → thin cylinders + cones, dark blue #2a4a6a (light #6a9ac4 near attn)
// time node t           → SphereGeometry(0.18) blue
// time embedding fans   → thin lines from t up to each block base
// dim labels            → addLabel above each block
// legend                → PlaneGeometry(2, 0.9) with two label arrows

const ORANGE = 0xa34a2a;
const ORANGE_DARK = 0x7a2f18;
const SKIP = 0xc96a3a;
const DARKBLUE = 0x2a4a6a;
const LIGHTBLUE = 0x6a9ac4;
const TNODE = 0x3a6aa8;

// ---------- helpers ----------
function makeBox(w, h, d, colorFront=ORANGE, colorSide=ORANGE_DARK, frontTex=null){
  const geom = new THREE.BoxGeometry(w, h, d);
  const matSide = new THREE.MeshBasicMaterial({ color: colorSide });
  const matTop  = new THREE.MeshBasicMaterial({ color: colorFront });
  const matFront = frontTex
    ? new THREE.MeshBasicMaterial({ map: frontTex })
    : new THREE.MeshBasicMaterial({ color: colorFront });
  // BoxGeometry face order: +X, -X, +Y, -Y, +Z, -Z
  const mats = [matSide, matSide, matTop, matSide, matFront, matSide];
  const mesh = new THREE.Mesh(geom, mats);
  // outline
  const edges = new THREE.LineSegments(
    new THREE.EdgesGeometry(geom),
    new THREE.LineBasicMaterial({ color: 0x2a1208, linewidth: 1 })
  );
  mesh.add(edges);
  return mesh;
}

function makeNoiseTexture(seed=1, size=128){
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext('2d');
  const img = ctx.createImageData(size, size);
  let s = seed;
  for (let i=0;i<size*size;i++){
    s = (s*1103515245+12345) & 0x7fffffff;
    const v = (s>>8) & 0xff;
    img.data[i*4] = v;
    img.data[i*4+1] = (v*7)&0xff;
    img.data[i*4+2] = (v*13)&0xff;
    img.data[i*4+3] = 255;
  }
  ctx.putImageData(img, 0, 0);
  const tex = new THREE.CanvasTexture(canvas);
  tex.needsUpdate = true;
  return tex;
}

function makeImageTexture(){
  // A vaguely skin-like reddish-brown noisy patch to stand in for the input photo.
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = 128;
  const ctx = canvas.getContext('2d');
  const grad = ctx.createRadialGradient(64,64,10,64,64,90);
  grad.addColorStop(0, '#c78a6a');
  grad.addColorStop(1, '#6a3a28');
  ctx.fillStyle = grad;
  ctx.fillRect(0,0,128,128);
  // dark blotch
  ctx.fillStyle = 'rgba(30,15,10,0.55)';
  ctx.beginPath(); ctx.ellipse(56,72,18,12,0.5,0,Math.PI*2); ctx.fill();
  // freckle-like specks
  for (let i=0;i<400;i++){
    ctx.fillStyle = `rgba(${40+Math.random()*60},${20+Math.random()*30},${10+Math.random()*20},${Math.random()*0.5})`;
    ctx.fillRect(Math.random()*128,Math.random()*128,1.5,1.5);
  }
  const tex = new THREE.CanvasTexture(canvas);
  tex.needsUpdate = true;
  return tex;
}

// Arrow (thin) — a cylinder shaft + cone head between two points
function makeArrow(from, to, color=DARKBLUE, radius=0.02){
  const g = new THREE.Group();
  const dir = new THREE.Vector3().subVectors(to, from);
  const len = dir.length();
  if (len < 1e-4) return g;
  const shaftLen = Math.max(0.01, len - 0.09);
  const shaftGeom = new THREE.CylinderGeometry(radius, radius, shaftLen, 8);
  const mat = new THREE.MeshBasicMaterial({ color });
  const shaft = new THREE.Mesh(shaftGeom, mat);
  shaft.position.copy(from).add(dir.clone().multiplyScalar(shaftLen/(2*len)));
  // orient
  const up = new THREE.Vector3(0,1,0);
  const q = new THREE.Quaternion().setFromUnitVectors(up, dir.clone().normalize());
  shaft.quaternion.copy(q);
  g.add(shaft);
  const headGeom = new THREE.ConeGeometry(radius*3, 0.09, 10);
  const head = new THREE.Mesh(headGeom, mat);
  head.position.copy(from).add(dir.clone().multiplyScalar((shaftLen+0.045)/len));
  head.quaternion.copy(q);
  g.add(head);
  g.userData.material = mat;
  return g;
}

// Curved skip-connection arrow (Bezier arc above)
function makeSkipArc(from, to, color=SKIP){
  const mid = new THREE.Vector3(
    (from.x+to.x)/2,
    Math.max(from.y, to.y) + 1.6,
    (from.z+to.z)/2
  );
  const curve = new THREE.QuadraticBezierCurve3(from, mid, to);
  const tube = new THREE.TubeGeometry(curve, 64, 0.025, 8, false);
  const mat = new THREE.MeshBasicMaterial({ color });
  const mesh = new THREE.Mesh(tube, mat);
  // arrowhead at end
  const tEnd = 0.985;
  const p1 = curve.getPoint(tEnd);
  const p2 = curve.getPoint(1);
  const dir = new THREE.Vector3().subVectors(p2, p1).normalize();
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.07, 0.18, 12), mat);
  head.position.copy(p2);
  const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0,1,0), dir);
  head.quaternion.copy(q);
  const g = new THREE.Group();
  g.add(mesh); g.add(head);
  g.userData.material = mat;
  g.userData.curve = curve;
  g.userData.midpoint = mid;
  return g;
}

// ---------- layout ----------
// Blocks: [id, w(face), h(face), d(depth), dimsLabel, isAttn]
const encoderSpec = [
  { id:'input',  w:3.0, h:3.0, d:0.05, dim:'256×256×3',   attn:false, isImage:true },
  { id:'e256',   w:3.0, h:3.0, d:1.6,  dim:'256×256×128', attn:false },
  { id:'e128',   w:1.6, h:1.6, d:1.6,  dim:'128×128×128', attn:false },
  { id:'e64',    w:0.9, h:0.9, d:3.2,  dim:'64×64×256',   attn:false },
  { id:'e32',    w:0.5, h:0.5, d:3.2,  dim:'32×32×256',   attn:false },
  { id:'e16',    w:0.32,h:0.32,d:6.0,  dim:'16×16×512',   attn:true  },
  { id:'b8',     w:0.18,h:0.18,d:6.0,  dim:'8×8×512',     attn:false },
];
const decoderSpec = [
  { id:'d16',    w:0.32,h:0.32,d:6.0,  dim:null, attn:true  },
  { id:'d32',    w:0.5, h:0.5, d:3.2,  dim:null, attn:false },
  { id:'d64',    w:0.9, h:0.9, d:3.2,  dim:null, attn:false },
  { id:'d128',   w:1.6, h:1.6, d:1.6,  dim:null, attn:false },
  { id:'d256',   w:3.0, h:3.0, d:1.6,  dim:null, attn:false },
  { id:'output', w:3.0, h:3.0, d:0.05, dim:null, attn:false, isNoise:true },
];

const blocks = {};  // id → { mesh, xCenter, topY, bottomY, spec }

// Pack encoder from left to right; bottom-aligned (bottom face at y=BASE_Y)
const BASE_Y = -1.5;   // common baseline for all blocks
let cursorX = -8.5;
const GAP = 0.12;

function placeRow(specs, startX){
  let x = startX;
  const out = [];
  for (const s of specs){
    const mesh = makeBox(s.w, s.h, s.d, ORANGE, ORANGE_DARK,
      s.isImage ? makeImageTexture() :
      s.isNoise ? makeNoiseTexture(42) : null);
    // We want depth to recede along +Z (upper-right in oblique shear)
    // Box already extends symmetrically; position center at (x + w/2, BASE_Y + h/2, d/2)
    const cx = x + s.w/2;
    mesh.position.set(cx, BASE_Y + s.h/2, s.d/2);
    scene.add(mesh);
    out.push({ mesh, xCenter: cx, cx, w:s.w, h:s.h, d:s.d, topY:BASE_Y+s.h, bottomY:BASE_Y, spec:s, id:s.id });
    x += s.w + GAP;
  }
  return { items: out, endX: x };
}

const encPlaced = placeRow(encoderSpec, cursorX);
// small gap between encoder and decoder
const decPlaced = placeRow(decoderSpec, encPlaced.endX + 0.3);

const allItems = [...encPlaced.items, ...decPlaced.items];
for (const it of allItems) blocks[it.id] = it;

// ---------- dimension labels ----------
function labelOffsetFor(item){
  // label above top-back corner of the block (world-space); oblique shear will place it up-right
  const zBack = item.d;   // back face
  const yTop = item.topY + 0.15;
  return new THREE.Vector3(item.cx, yTop, zBack);
}
for (const item of encPlaced.items){
  if (!item.spec.dim) continue;
  addLabel(item.spec.dim, labelOffsetFor(item), { fontSize:'10px', color:'#3a1a0a' });
}

// ---------- skip connections ----------
// Match encoder to decoder at 256, 128, 64, 32
const skipPairs = [
  ['e256','d256'],
  ['e128','d128'],
  ['e64','d64'],
  ['e32','d32'],
];
const skipArcs = {};
for (const [a,b] of skipPairs){
  const A = blocks[a], B = blocks[b];
  const from = new THREE.Vector3(A.cx, A.topY, A.d);
  const to   = new THREE.Vector3(B.cx, B.topY, B.d);
  const arc = makeSkipArc(from, to, SKIP);
  scene.add(arc);
  skipArcs[a+'>'+b] = arc;
  // Concatenate label at midpoint
  const mid = arc.userData.midpoint.clone();
  mid.y += 0.15;
  addLabel('Concatenate', mid, { fontSize:'11px', color:'#8a3a1a' });
}

// ---------- bottom residual arrow chain ----------
// One arrow between each successive block, at y=BASE_Y-0.35, z=0 (front face)
const chainIds = ['input','e256','e128','e64','e32','e16','b8','d16','d32','d64','d128','d256','output'];
const chainArrows = [];
for (let i=0;i<chainIds.length-1;i++){
  const A = blocks[chainIds[i]], B = blocks[chainIds[i+1]];
  // Arrow goes from A's front-bottom-right toward B's front-bottom-left, but simplified along X
  const yA = BASE_Y - 0.35;
  const from = new THREE.Vector3(A.cx + A.w*0.5, yA, 0);
  const to   = new THREE.Vector3(B.cx - B.w*0.5, yA, 0);
  // Lighter color if either endpoint is an attention block edge
  const isLight = (blocks[chainIds[i]].spec.attn) || (blocks[chainIds[i+1]].spec.attn);
  const color = isLight ? LIGHTBLUE : DARKBLUE;
  const arr = makeArrow(from, to, color, 0.022);
  scene.add(arr);
  arr.userData.baseColor = color;
  arr.userData.fromId = chainIds[i];
  arr.userData.toId = chainIds[i+1];
  chainArrows.push(arr);
}

// ---------- time embedding node t ----------
const tGroup = new THREE.Group();
const tNode = new THREE.Mesh(
  new THREE.CircleGeometry(0.22, 24),
  new THREE.MeshBasicMaterial({ color: 0xffffff })
);
tNode.position.set(-9.2, BASE_Y - 1.3, 0);
scene.add(tNode);
const tRing = new THREE.Mesh(
  new THREE.RingGeometry(0.22, 0.26, 24),
  new THREE.MeshBasicMaterial({ color: DARKBLUE })
);
tRing.position.copy(tNode.position);
scene.add(tRing);
addLabel('t', tNode.position.clone(), { fontSize:'12px', color:'#2a4a6a', bold:true });
addLabel('time embedding', new THREE.Vector3(-8.2, BASE_Y - 1.55, 0), { fontSize:'11px', color:'#2a4a6a' });

// Fan of arrows from t to base of each block (except input which is the image itself)
const timeArrows = [];
const timeTargets = ['e256','e128','e64','e32','e16','b8','d16','d32','d64','d128','d256','output'];
for (const id of timeTargets){
  const B = blocks[id];
  const from = new THREE.Vector3(tNode.position.x + 0.2, tNode.position.y, 0);
  const to = new THREE.Vector3(B.cx, BASE_Y - 0.35, 0);
  const arr = makeArrow(from, to, DARKBLUE, 0.012);
  arr.userData.baseColor = DARKBLUE;
  scene.add(arr);
  timeArrows.push(arr);
}

// ---------- legend ----------
