// ---------- self-attention overlay (16×16 dot grid over enc16) ----------
const attnGroup = new THREE.Group();
attnGroup.visible = false;
scene.add(attnGroup);
{
  const N = 16;
  const target = blocks['e16'];
  const cx = target.cx;
  const cy = target.topY + 1.2;
  const cz = target.d/2;
  const gridSize = 1.2;
  const positions = [];
  const dotGeom = new THREE.CircleGeometry(0.018, 8);
  const dotMat = new THREE.MeshBasicMaterial({ color: 0x333333 });
  for (let i=0;i<N;i++){
    for (let j=0;j<N;j++){
      const x = cx + (i/(N-1) - 0.5) * gridSize;
      const y = cy + (j/(N-1) - 0.5) * gridSize;
      const p = new THREE.Vector3(x, y, cz);
      positions.push(p);
      const dot = new THREE.Mesh(dotGeom, dotMat);
      dot.position.copy(p);
      attnGroup.add(dot);
    }
  }
  // highlight query at center
  const qi = 8, qj = 8;
  const queryIdx = qi*N + qj;
  const qDot = new THREE.Mesh(new THREE.CircleGeometry(0.04, 12),
    new THREE.MeshBasicMaterial({ color: 0xd94a2a }));
  qDot.position.copy(positions[queryIdx]);
  qDot.position.z += 0.01;
  attnGroup.add(qDot);
  // lines from query to all others
  const lineMat = new THREE.LineBasicMaterial({ color: 0xd94a2a, transparent:true, opacity:0.18 });
  const linePts = [];
  for (let k=0;k<positions.length;k++){
    if (k===queryIdx) continue;
    linePts.push(positions[queryIdx].clone());
    linePts.push(positions[k].clone());
  }
  const lineGeom = new THREE.BufferGeometry().setFromPoints(linePts);
  const lines = new THREE.LineSegments(lineGeom, lineMat);
  attnGroup.add(lines);
  // caption
  const capPos = new THREE.Vector3(cx, cy + 0.75, cz);
  const cap = document.createElement('div');
  cap.className = 'lbl';
  cap.innerHTML = 'self-attention: 256 positions, all-to-all';
  cap.style.fontSize = '10px';
  cap.style.color = '#a03018';
  cap.style.background = 'rgba(255,255,255,0.7)';
  cap.style.padding = '1px 4px';
  cap.style.borderRadius = '3px';
  document.getElementById('stage').appendChild(cap);
  const capEntry = { div: cap, pos: capPos.clone(), offset:[0,0] };
  _labels.push(capEntry);
  attnGroup.userData.captionEntry = capEntry;
  cap.style.display = 'none';
  attnGroup.userData.captionDiv = cap;
}

// ---------- time embedding bar (visualise 8-D vector) ----------
const embBarGroup = new THREE.Group();
scene.add(embBarGroup);
const embBars = [];
for (let k=0;k<8;k++){
  const bar = new THREE.Mesh(
    new THREE.PlaneGeometry(0.09, 0.4),
    new THREE.MeshBasicMaterial({ color: DARKBLUE })
  );
  bar.position.set(tNode.position.x + 0.55 + k*0.11, tNode.position.y, 0.01);
  embBarGroup.add(bar);
  embBars.push(bar);
}

function computeEmbedding(t){
  const d = 8;
  const out = [];
  for (let k=0;k<d;k++){
    const denom = Math.pow(10000, (2*Math.floor(k/2))/d);
    const v = (k % 2 === 0) ? Math.sin(t/denom) : Math.cos(t/denom);
    out.push(v);
  }
  return out;
}

function updateEmbeddingVis(t){
  const emb = computeEmbedding(t);
  for (let k=0;k<embBars.length;k++){
    const v = emb[k];
    const mag = Math.abs(v);
    embBars[k].scale.y = 0.2 + mag*1.2;
    // color: red for positive, blue for negative
    const col = new THREE.Color();
    if (v >= 0) col.setRGB(0.7 + 0.3*mag, 0.4*(1-mag), 0.2*(1-mag));
    else col.setRGB(0.2*(1-mag), 0.35, 0.6 + 0.35*mag);
    embBars[k].material.color.copy(col);
  }
  // tint time embedding arrows by dominant sign
  let dom = 0; for (const v of emb) dom += v;
  const tint = new THREE.Color();
  if (dom >= 0) tint.setRGB(0.35, 0.45, 0.65);
  else tint.setRGB(0.55, 0.55, 0.75);
  // blend with base for subtle effect
  for (const a of timeArrows){
    a.userData.material.color.copy(tint);
  }
}

// ---------- state & highlighting ----------
const flowStates = ['input','e256','e128','e64','e32','e16','b8','d16','d32','d64','d128','d256','output'];
const state = { flowStep: 'input', t: 500, inspectAttention: false };

function setHighlight(){
  // Reset all block emissive-ish tint by scaling color; here we tweak via emissive proxy = darker if inactive.
  const activeIdx = flowStates.indexOf(state.flowStep);
  for (let i=0;i<flowStates.length;i++){
    const it = blocks[flowStates[i]];
    if (!it) continue;
    const mats = it.mesh.material;
    const isActive = i === activeIdx;
    const isBefore = i < activeIdx;
    // apply per-material colour
    for (let mi=0; mi<mats.length; mi++){
      const m = mats[mi];
      if (!m) continue;
      if (mi === 4 && (it.spec.isImage || it.spec.isNoise)){
        // keep texture; don't recolor
        continue;
      }
      const base = (mi === 2 || mi === 4) ? ORANGE : ORANGE_DARK;
      let c = new THREE.Color(base);
      if (isActive) {
        c.lerp(new THREE.Color(0xffcc66), 0.55);  // bright pulse
      } else if (!isBefore) {
        c.multiplyScalar(0.55); // future = darker
      }
      m.color.copy(c);
    }
  }
  // chain arrows highlight
  for (const a of chainArrows){
    const iFrom = flowStates.indexOf(a.userData.fromId);
    const iTo   = flowStates.indexOf(a.userData.toId);
    const base = new THREE.Color(a.userData.baseColor);
    if (iTo === activeIdx){
      base.lerp(new THREE.Color(0xffcc66), 0.5); // pulse
    } else if (iTo > activeIdx){
      base.multiplyScalar(0.5);
    }
    a.userData.material.color.copy(base);
  }
  // skip arcs: pulse when active step is a decoder scale with matching skip
  const decodeToEnc = { d256:'e256', d128:'e128', d64:'e64', d32:'e32' };
  for (const [pairKey, arc] of Object.entries(skipArcs)){
    const [encId, decId] = pairKey.split('>');
    let c = new THREE.Color(SKIP);
    if (state.flowStep === decId) {
      c.lerp(new THREE.Color(0xffff66), 0.55);
    } else {
      c.multiplyScalar(0.9);
    }
    arc.userData.material.color.copy(c);
  }
  // attention overlay visibility
  const showAttn = state.inspectAttention && (state.flowStep === 'e16' || state.flowStep === 'd16');
  attnGroup.visible = showAttn;
  if (attnGroup.userData.captionDiv){
    attnGroup.userData.captionDiv.style.display = showAttn ? '' : 'none';
  }
}

// ---------- UI wiring ----------
const btnStep = document.getElementById('btnStep');
const btnPlay = document.getElementById('btnPlay');
const slT = document.getElementById('slT');
const tVal = document.getElementById('tVal');
const chkAttn = document.getElementById('chkAttn');
const stepInfo = document.getElementById('stepInfo');

const stepLabels = {
  input:'input', e256:'enc 256²×128', e128:'enc 128²×128', e64:'enc 64²×256',
  e32:'enc 32²×256', e16:'enc 16²×512 (attn)', b8:'bottleneck 8²×512',
  d16:'dec 16²×512 (attn)', d32:'dec 32²×256', d64:'dec 64²×256',
  d128:'dec 128²×128', d256:'dec 256²×128', output:'output ε̂'
};

btnStep.addEventListener('click', ()=>{
  const cur = flowStates.indexOf(state.flowStep);
  const nxt = (cur+1) % flowStates.length;
  state.flowStep = flowStates[nxt];
  btnStep.textContent = 'Step: ' + stepLabels[state.flowStep];
  stepInfo.textContent = 'Now at: ' + stepLabels[state.flowStep];
  setHighlight();
});

slT.addEventListener('input', ()=>{
  state.t = parseInt(slT.value, 10);
  tVal.textContent = state.t;
  updateEmbeddingVis(state.t);
});

chkAttn.addEventListener('change', ()=>{
  state.inspectAttention = chkAttn.checked;
  setHighlight();
});

