function placeRow(specs, startX){
  let x = startX;
  const out = [];
  for (const s of specs){
    const mesh = makeBox(s.w, s.h, s.d, ORANGE, ORANGE_DARK,
      s.isImage ? makeImageTexture() :
      s.isNoise ? makeNoiseTexture(42) : null);
    // We want depth to recede along +Z (upper-right in oblique shear)
    // Box already extends symmetrically; position center at (x + w/2, BASE_Y + h/2, d/2)
    const cx = x + s.w/2;
    mesh.position.set(cx, BASE_Y + s.h/2, s.d/2);
    scene.add(mesh);
    out.push({ mesh, xCenter: cx, cx, w:s.w, h:s.h, d:s.d, topY:BASE_Y+s.h, bottomY:BASE_Y, spec:s, id:s.id });
