    const isBefore = i < activeIdx;
    for (let mi=0; mi<mats.length; mi++){
      const m = mats[mi];
      if (!m) continue;
      if ((mi === 4) && (it.spec.isImage || it.spec.isNoise)) continue;
      const base = (mi === 2 || mi === 4) ? ORANGE : ORANGE_DARK;
      let c = new THREE.Color(base);
      if (isActive) c.lerp(new THREE.Color(0xffcc66), 0.55);
