function makeBox(w, h, d, frontTex=null){
  const geom = new THREE.BoxGeometry(w, h, d);
  const matSide = new THREE.MeshBasicMaterial({ color: ORANGE_DARK });
  const matTop  = new THREE.MeshBasicMaterial({ color: ORANGE });
  const matFront = frontTex
    ? new THREE.MeshBasicMaterial({ map: frontTex })
    : new THREE.MeshBasicMaterial({ color: ORANGE });
  const mats = [matSide, matSide, matTop, matSide, matFront, matSide];
  const mesh = new THREE.Mesh(geom, mats);
  const edges = new THREE.LineSegments(
    new THREE.EdgesGeometry(geom),
    new THREE.LineBasicMaterial({ color: 0x2a1208 })
  );
  mesh.add(edges);
  return mesh;
}

function makeNoiseTexture(seed=1, size=128){
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext('2d');
  const img = ctx.createImageData(size, size);
  let s = seed;
  for (let i=0;i<size*size;i++){
    s = (s*1103515245+12345) & 0x7fffffff;
    const v = (s>>8) & 0xff;
    img.data[i*4] = v;
    img.data[i*4+1] = (v*7)&0xff;
    img.data[i*4+2] = (v*13)&0xff;
    img.data[i*4+3] = 255;
  }
  ctx.putImageData(img, 0, 0);
  const tex = new THREE.CanvasTexture(canvas);
  tex.needsUpdate = true;
  return tex;
}

function makeImageTexture(){
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = 128;
  const ctx = canvas.getContext('2d');
  const grad = ctx.createRadialGradient(64,64,10,64,64,90);
  grad.addColorStop(0, '#c78a6a');
  grad.addColorStop(1, '#6a3a28');
  ctx.fillStyle = grad;
  ctx.fillRect(0,0,128,128);
  ctx.fillStyle = 'rgba(30,15,10,0.55)';
  ctx.beginPath(); ctx.ellipse(56,72,18,12,0.5,0,Math.PI*2); ctx.fill();
  for (let i=0;i<400;i++){
    ctx.fillStyle = `rgba(${40+Math.random()*60},${20+Math.random()*30},${10+Math.random()*20},${Math.random()*0.5})`;
    ctx.fillRect(Math.random()*128,Math.random()*128,1.5,1.5);
  }
  const tex = new THREE.CanvasTexture(canvas);
  tex.needsUpdate = true;
  return tex;
}

function makeArrow(from, to, color=DARKBLUE, radius=0.025){
  const g = new THREE.Group();
  const dir = new THREE.Vector3().subVectors(to, from);
  const len = dir.length();
  if (len < 1e-4) return g;
  const headLen = Math.min(0.14, len*0.35);
  const shaftLen = Math.max(0.01, len - headLen);
  const shaftGeom = new THREE.CylinderGeometry(radius, radius, shaftLen, 8);
  const mat = new THREE.MeshBasicMaterial({ color });
  const shaft = new THREE.Mesh(shaftGeom, mat);
  shaft.position.copy(from).add(dir.clone().multiplyScalar(shaftLen/(2*len)));
  const up = new THREE.Vector3(0,1,0);
  const q = new THREE.Quaternion().setFromUnitVectors(up, dir.clone().normalize());
  shaft.quaternion.copy(q);
  g.add(shaft);
  const headGeom = new THREE.ConeGeometry(radius*3.2, headLen, 12);
  const head = new THREE.Mesh(headGeom, mat);
  head.position.copy(from).add(dir.clone().multiplyScalar((shaftLen + headLen/2)/len));
  head.quaternion.copy(q);
  g.add(head);
  g.userData.material = mat;
  return g;
}

function makeSkipArc(from, to, arcHeight, color=SKIP){
  const mid = new THREE.Vector3(
    (from.x+to.x)/2,
    arcHeight,
    (from.z+to.z)/2
  );
  // Use two segments: up from source, across at height, down to target -> approximate with two quadratic curves? Simpler: a curve with rounded corners via CatmullRom
  const p0 = from.clone();
  const p1 = new THREE.Vector3(from.x + 0.1, arcHeight, from.z);
  const p2 = new THREE.Vector3(to.x - 0.1, arcHeight, to.z);
  const p3 = to.clone();
  const curve = new THREE.CatmullRomCurve3([p0, p1, p2, p3], false, 'catmullrom', 0.2);
  const tube = new THREE.TubeGeometry(curve, 80, 0.028, 8, false);
  const mat = new THREE.MeshBasicMaterial({ color });
  const mesh = new THREE.Mesh(tube, mat);
  const pEnd = curve.getPoint(1);
  const pPre = curve.getPoint(0.98);
  const dir = new THREE.Vector3().subVectors(pEnd, pPre).normalize();
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.09, 0.22, 14), mat);
  head.position.copy(pEnd);
  const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0,1,0), dir);
  head.quaternion.copy(q);
  const g = new THREE.Group();
  g.add(mesh); g.add(head);
  g.userData.material = mat;
  g.userData.midPos = new THREE.Vector3((from.x+to.x)/2, arcHeight, 0);
  return g;
}

