function projectFromCameraToPlane(cameraCenter, objectPoint, planeCenter, planeNormal) {
  const ray = new THREE.Vector3().subVectors(objectPoint, cameraCenter);
  const denom = planeNormal.dot(ray);
  if (Math.abs(denom) < 1e-7) return planeCenter.clone();
  const t = planeNormal.dot(new THREE.Vector3().subVectors(planeCenter, cameraCenter)) / denom;
  return cameraCenter.clone().addScaledVector(ray, t);
}

function clipLineToPlaneRect(a, b, center, u, v, width, height) {
  const ap = new THREE.Vector3().subVectors(a, center);
  const bp = new THREE.Vector3().subVectors(b, center);
  const ax = ap.dot(u), ay = ap.dot(v);
  const bx = bp.dot(u), by = bp.dot(v);
  const dx = bx - ax, dy = by - ay;
  const hw = width / 2, hh = height / 2;
  const ts = [];

  function addT(t) {
    if (!Number.isFinite(t)) return;
    const x = ax + dx * t;
    const y = ay + dy * t;
    if (x >= -hw - 1e-5 && x <= hw + 1e-5 && y >= -hh - 1e-5 && y <= hh + 1e-5) ts.push(t);
  }

  if (Math.abs(dx) > 1e-9) {
    addT((-hw - ax) / dx);
    addT((hw - ax) / dx);
  }
  if (Math.abs(dy) > 1e-9) {
    addT((-hh - ay) / dy);
    addT((hh - ay) / dy);
  }

  ts.sort((m, n) => m - n);
  const unique = ts.filter((t, i) => i === 0 || Math.abs(t - ts[i - 1]) > 1e-4);
  if (unique.length >= 2) return [a.clone().lerp(b, unique[0]), a.clone().lerp(b, unique[unique.length - 1])];

  const localDir = new THREE.Vector2(dx, dy);
  if (localDir.lengthSq() < 1e-9) {
    return [
      center.clone().addScaledVector(u, -hw),
      center.clone().addScaledVector(u, hw)
    ];
  }
  localDir.normalize();
  const local = new THREE.Vector2(ax, ay);
  const tClosest = -local.dot(localDir);
  const cx = ax + localDir.x * tClosest;
  const cy = ay + localDir.y * tClosest;
  const span = Math.sqrt(hw * hw + hh * hh);
  return [
    center.clone().addScaledVector(u, cx - localDir.x * span).addScaledVector(v, cy - localDir.y * span),
    center.clone().addScaledVector(u, cx + localDir.x * span).addScaledVector(v, cy + localDir.y * span)
  ];
}

function addCurvedArrow(parent, start, control, end, color, radius = 0.032) {
