// @FIGURE_CODE_BEGIN
// Element specs (per plan):
// input slab 256x256x3        → BoxGeometry(3.0, 3.0, 0.05)   image texture front
// enc 256x256x128             → BoxGeometry(3.0, 3.0, 1.6)    #a34a2a / side #7a2f18
// enc 128x128x128             → BoxGeometry(1.6, 1.6, 1.6)
// enc 64x64x256               → BoxGeometry(0.9, 0.9, 3.2)
// enc 32x32x256               → BoxGeometry(0.5, 0.5, 3.2)
// enc 16x16x512               → BoxGeometry(0.28, 0.28, 6.0)  self-attention
// bottleneck 8x8x512          → BoxGeometry(0.15, 0.15, 6.0)
// decoder mirrors on right, same shapes reversed
// output slab                 → BoxGeometry(3.0, 3.0, 0.05)   noise texture
// skip arcs                   → CatmullRomCurve3 → TubeGeometry + cone head, #c96a3a
// residual chain arrows       → cylinder+cone, #2a4a6a; lighter #6a9ac4 near attn
// t node                      → CircleGeometry with ring, DARKBLUE
// time-embedding fan          → thin arrows rising into each block base
// dim labels                  → addLabel above each block (small dark-brown)
// legend                      → PlaneGeometry with two arrow swatches, upper-left

const ORANGE = 0xa34a2a;
const ORANGE_DARK = 0x7a2f18;
const SKIP = 0xc96a3a;
const DARKBLUE = 0x2a4a6a;
const LIGHTBLUE = 0x6a9ac4;

function makeBox(w, h, d, frontTex=null){
  const geom = new THREE.BoxGeometry(w, h, d);
  const matSide = new THREE.MeshBasicMaterial({ color: ORANGE_DARK });
  const matTop  = new THREE.MeshBasicMaterial({ color: ORANGE });
  const matFront = frontTex
    ? new THREE.MeshBasicMaterial({ map: frontTex })
    : new THREE.MeshBasicMaterial({ color: ORANGE });
  const mats = [matSide, matSide, matTop, matSide, matFront, matSide];
  const mesh = new THREE.Mesh(geom, mats);
  const edges = new THREE.LineSegments(
    new THREE.EdgesGeometry(geom),
    new THREE.LineBasicMaterial({ color: 0x2a1208 })
  );
  mesh.add(edges);
  return mesh;
}

function makeNoiseTexture(seed=1, size=128){
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext('2d');
  const img = ctx.createImageData(size, size);
  let s = seed;
  for (let i=0;i<size*size;i++){
    s = (s*1103515245+12345) & 0x7fffffff;
    const v = (s>>8) & 0xff;
    img.data[i*4] = v;
    img.data[i*4+1] = (v*7)&0xff;
    img.data[i*4+2] = (v*13)&0xff;
    img.data[i*4+3] = 255;
  }
  ctx.putImageData(img, 0, 0);
  const tex = new THREE.CanvasTexture(canvas);
  tex.needsUpdate = true;
  return tex;
}

function makeImageTexture(){
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = 128;
  const ctx = canvas.getContext('2d');
  const grad = ctx.createRadialGradient(64,64,10,64,64,90);
  grad.addColorStop(0, '#c78a6a');
  grad.addColorStop(1, '#5a3020');
  ctx.fillStyle = grad;
  ctx.fillRect(0,0,128,128);
  ctx.fillStyle = 'rgba(30,15,10,0.55)';
  ctx.beginPath(); ctx.ellipse(56,72,18,12,0.5,0,Math.PI*2); ctx.fill();
  for (let i=0;i<400;i++){
    ctx.fillStyle = `rgba(${40+Math.random()*60},${20+Math.random()*30},${10+Math.random()*20},${Math.random()*0.5})`;
    ctx.fillRect(Math.random()*128,Math.random()*128,1.5,1.5);
  }
  const tex = new THREE.CanvasTexture(canvas);
  tex.needsUpdate = true;
  return tex;
}

function makeArrow(from, to, color=DARKBLUE, radius=0.025){
  const g = new THREE.Group();
  const dir = new THREE.Vector3().subVectors(to, from);
  const len = dir.length();
  if (len < 1e-4) return g;
  const headLen = Math.min(0.14, len*0.35);
  const shaftLen = Math.max(0.01, len - headLen);
  const shaftGeom = new THREE.CylinderGeometry(radius, radius, shaftLen, 8);
  const mat = new THREE.MeshBasicMaterial({ color });
  const shaft = new THREE.Mesh(shaftGeom, mat);
  shaft.position.copy(from).add(dir.clone().multiplyScalar(shaftLen/(2*len)));
  const up = new THREE.Vector3(0,1,0);
  const q = new THREE.Quaternion().setFromUnitVectors(up, dir.clone().normalize());
  shaft.quaternion.copy(q);
  g.add(shaft);
  const headGeom = new THREE.ConeGeometry(radius*3.2, headLen, 12);
  const head = new THREE.Mesh(headGeom, mat);
  head.position.copy(from).add(dir.clone().multiplyScalar((shaftLen + headLen/2)/len));
  head.quaternion.copy(q);
  g.add(head);
  g.userData.material = mat;
  return g;
}

function makeSkipArc(from, to, arcHeight, color=SKIP){
  const p0 = from.clone();
  const p1 = new THREE.Vector3(from.x + 0.15, arcHeight, from.z);
  const p2 = new THREE.Vector3(to.x - 0.15, arcHeight, to.z);
  const p3 = to.clone();
  const curve = new THREE.CatmullRomCurve3([p0, p1, p2, p3], false, 'catmullrom', 0.15);
  const tube = new THREE.TubeGeometry(curve, 100, 0.022, 8, false);
  const mat = new THREE.MeshBasicMaterial({ color });
  const mesh = new THREE.Mesh(tube, mat);
  const pEnd = curve.getPoint(1);
  const pPre = curve.getPoint(0.985);
  const dir = new THREE.Vector3().subVectors(pEnd, pPre).normalize();
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.07, 0.18, 14), mat);
  head.position.copy(pEnd);
  const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0,1,0), dir);
  head.quaternion.copy(q);
  const g = new THREE.Group();
  g.add(mesh); g.add(head);
  g.userData.material = mat;
  g.userData.labelPos = new THREE.Vector3((from.x+to.x)/2, arcHeight + 0.18, 0);
  return g;
}

// ---------- layout ----------
// Wider horizontal spread so blocks don't overlap; skip arcs will span far.
const encoderSpec = [
  { id:'input',  w:3.0, h:3.0, d:0.05, dim:'256×256×3',   isImage:true },
  { id:'e256',   w:3.0, h:3.0, d:1.6,  dim:'256×256×128' },
  { id:'e128',   w:1.6, h:1.6, d:1.6,  dim:'128×128×128' },
  { id:'e64',    w:0.9, h:0.9, d:3.2,  dim:'64×64×256'   },
  { id:'e32',    w:0.5, h:0.5, d:3.2,  dim:'32×32×256'   },
  { id:'e16',    w:0.35,h:0.35,d:6.0,  dim:'16×16×512', attn:true },
  { id:'b8',     w:0.22,h:0.22,d:6.0,  dim:'8×8×512'    },
];
const decoderSpec = [
  { id:'d16',    w:0.35,h:0.35,d:6.0, attn:true },
  { id:'d32',    w:0.5, h:0.5, d:3.2 },
  { id:'d64',    w:0.9, h:0.9, d:3.2 },
  { id:'d128',   w:1.6, h:1.6, d:1.6 },
  { id:'d256',   w:3.0, h:3.0, d:1.6 },
  { id:'output', w:3.0, h:3.0, d:0.05, isNoise:true },
];

const blocks = {};

// Baseline at bottom; blocks are bottom-aligned so shorter blocks sit low.
const BASE_Y = -2.2;
// Generous per-block gap so nothing overlaps. Front face width is used
// for footprint; extra padding between blocks scales with the larger of
// the two adjacent depths so deep bars keep breathing room.
const GAP_MIN = 0.55;

function placeRow(specs, startX){
  let x = startX;
  const out = [];
  for (let i=0;i<specs.length;i++){
    const s = specs[i];
    const mesh = makeBox(s.w, s.h, s.d,
      s.isImage ? makeImageTexture() :
      s.isNoise ? makeNoiseTexture(42) : null);
    const cx = x + s.w/2;
    // Bottom-aligned: mesh center y = BASE_Y + h/2; z centered so front face is at z=0.
    mesh.position.set(cx, BASE_Y + s.h/2, 0);
    scene.add(mesh);
    out.push({ mesh, cx, w:s.w, h:s.h, d:s.d, topY:BASE_Y+s.h, bottomY:BASE_Y, spec:s, id:s.id });
    const next = specs[i+1];
    const nextW = next ? next.w : 0;
    x += s.w + GAP_MIN + Math.max(0, (Math.max(s.w, nextW) - 1) * 0.05);
  }
  return { items: out, endX: x };
}

// Center the whole thing around x=0. Compute encoder start so that
// encoder+decoder together are roughly symmetric.
// Rough total width estimate
let estWidth = 0;
for (const s of [...encoderSpec, ...decoderSpec]) estWidth += s.w + GAP_MIN;
const encStart = -estWidth/2;

const encPlaced = placeRow(encoderSpec, encStart);
const decPlaced = placeRow(decoderSpec, encPlaced.endX + 0.3);
const allItems = [...encPlaced.items, ...decPlaced.items];
for (const it of allItems) blocks[it.id] = it;

// ---------- dimension labels ----------
// Labels sit ABOVE each block with a small pixel offset so they don't overlap geometry.
for (const item of encPlaced.items){
  if (!item.spec.dim) continue;
  const pos = new THREE.Vector3(item.cx, item.topY + 0.15, 0);
  addLabel(item.spec.dim, pos, { fontSize:'11px', color:'#2a1208', offset:[0, -8] });
}

// ---------- skip connections ----------
// Arc heights well above the tallest block (top ~0.8) so arcs span cleanly across.
// The tallest encoder block top is BASE_Y + 3.0 = 0.8. Arc levels above that.
const skipPairs = [
  ['e256','d256', 3.6],
  ['e128','d128', 2.9],
  ['e64','d64',   2.2],
  ['e32','d32',   1.5],
