}

// ---------- bottom residual arrow chain ----------
const chainIds = ['input','e256','e128','e64','e32','e16','b8','d16','d32','d64','d128','d256','output'];
const chainArrows = [];
const chainY = BASE_Y - 0.5;
for (let i=0;i<chainIds.length-1;i++){
  const A = blocks[chainIds[i]], B = blocks[chainIds[i+1]];
  const from = new THREE.Vector3(A.cx, chainY, 0);
  const to   = new THREE.Vector3(B.cx, chainY, 0);
  const isLight = A.spec.attn || B.spec.attn;
  const color = isLight ? LIGHTBLUE : DARKBLUE;
  const arr = makeArrow(from, to, color, 0.025);
  scene.add(arr);
  arr.userData.baseColor = color;
  arr.userData.toId = chainIds[i+1];
  chainArrows.push(arr);
}

// ---------- time embedding node t ----------
const tPos = new THREE.Vector3(encStart - 0.6, chainY - 0.9, 0);
const tCircle = new THREE.Mesh(
  new THREE.CircleGeometry(0.26, 32),
  new THREE.MeshBasicMaterial({ color: 0xffffff })
);
tCircle.position.copy(tPos);
scene.add(tCircle);
const tRing = new THREE.Mesh(
  new THREE.RingGeometry(0.26, 0.31, 32),
  new THREE.MeshBasicMaterial({ color: DARKBLUE })
);
tRing.position.copy(tPos);
scene.add(tRing);
addLabel('t', tPos.clone(), { fontSize:'14px', color:'#2a4a6a', bold:true });
addLabel('time embedding', new THREE.Vector3(tPos.x + 1.4, tPos.y, 0), { fontSize:'12px', color:'#2a4a6a' });

// horizontal spine from t running to end of chain
const spineFrom = new THREE.Vector3(tPos.x + 0.32, tPos.y, 0);
const spineTo   = new THREE.Vector3(blocks['output'].cx + 0.1, tPos.y, 0);
const spine = makeArrow(spineFrom, spineTo, DARKBLUE, 0.015);
scene.add(spine);

// vertical fan up into each block base
const timeArrows = [];
for (const id of chainIds){
  const B = blocks[id];
  const from = new THREE.Vector3(B.cx, tPos.y, 0);
  const to   = new THREE.Vector3(B.cx, chainY - 0.06, 0);
  const arr = makeArrow(from, to, DARKBLUE, 0.012);
  arr.userData.baseColor = DARKBLUE;
  scene.add(arr);
  timeArrows.push(arr);
}

// ---------- legend (upper-left) ----------
// Place above the encoder area near x = encStart, y just above tallest block.
const legendCx = encStart + 0.8;
const legendCy = 3.0;
const legendBg = new THREE.Mesh(
  new THREE.PlaneGeometry(2.4, 1.1),
  new THREE.MeshBasicMaterial({ color: 0xffffff })
);
legendBg.position.set(legendCx, legendCy, 0);
scene.add(legendBg);
const legendBorder = new THREE.LineSegments(
  new THREE.EdgesGeometry(new THREE.PlaneGeometry(2.4, 1.1)),
  new THREE.LineBasicMaterial({ color: 0x444444 })
);
legendBorder.position.set(legendCx, legendCy, 0.001);
scene.add(legendBorder);
scene.add(makeArrow(
  new THREE.Vector3(legendCx - 1.0, legendCy + 0.28, 0.01),
  new THREE.Vector3(legendCx - 0.55, legendCy + 0.28, 0.01),
  DARKBLUE, 0.022));
scene.add(makeArrow(
  new THREE.Vector3(legendCx - 1.0, legendCy - 0.24, 0.01),
  new THREE.Vector3(legendCx - 0.55, legendCy - 0.24, 0.01),
  LIGHTBLUE, 0.022));
addLabel('Res. block',
  new THREE.Vector3(legendCx + 0.15, legendCy + 0.28, 0.02),
  { fontSize:'12px', color:'#222' });
addLabel('Res. block +<br>self-attention',
  new THREE.Vector3(legendCx + 0.25, legendCy - 0.24, 0.02),
  { fontSize:'12px', color:'#222' });

// ---------- self-attention overlay ----------
const attnGroup = new THREE.Group();
attnGroup.visible = false;
scene.add(attnGroup);
const attnCaption = document.createElement('div');
attnCaption.className = 'lbl';
attnCaption.innerHTML = 'self-attention: 256 positions, all-to-all';
attnCaption.style.fontSize = '11px';
attnCaption.style.color = '#a03018';
attnCaption.style.background = 'rgba(255,255,255,0.85)';
attnCaption.style.padding = '2px 5px';
attnCaption.style.borderRadius = '3px';
attnCaption.style.display = 'none';
document.getElementById('stage').appendChild(attnCaption);
const attnCapEntry = { div: attnCaption, pos: new THREE.Vector3(0,0,0), offset:[0,0] };
_labels.push(attnCapEntry);
{
  const N = 16;
  const target = blocks['e16'];
  const cx = target.cx;
  const cy = target.topY + 1.2;
  const gridSize = 1.3;
  const positions = [];
  const dotGeom = new THREE.CircleGeometry(0.02, 8);
  const dotMat = new THREE.MeshBasicMaterial({ color: 0x333333 });
  for (let i=0;i<N;i++){
    for (let j=0;j<N;j++){
      const x = cx + (i/(N-1) - 0.5) * gridSize;
      const y = cy + (j/(N-1) - 0.5) * gridSize;
      const p = new THREE.Vector3(x, y, 0);
      positions.push(p);
      const dot = new THREE.Mesh(dotGeom, dotMat);
      dot.position.copy(p);
      attnGroup.add(dot);
    }
  }
  const queryIdx = 8*N + 8;
  const qDot = new THREE.Mesh(new THREE.CircleGeometry(0.045, 12),
    new THREE.MeshBasicMaterial({ color: 0xd94a2a }));
  qDot.position.copy(positions[queryIdx]);
  qDot.position.z += 0.02;
  attnGroup.add(qDot);
  const lineMat = new THREE.LineBasicMaterial({ color: 0xd94a2a, transparent:true, opacity:0.15 });
  const linePts = [];
  for (let k=0;k<positions.length;k++){
    if (k===queryIdx) continue;
    linePts.push(positions[queryIdx].clone());
    linePts.push(positions[k].clone());
  }
  const lineGeom = new THREE.BufferGeometry().setFromPoints(linePts);
  attnGroup.add(new THREE.LineSegments(lineGeom, lineMat));
