}

// ---------- time embedding vector bars next to t ----------
const embBars = [];
for (let k=0;k<8;k++){
  const bar = new THREE.Mesh(
    new THREE.PlaneGeometry(0.08, 0.4),
    new THREE.MeshBasicMaterial({ color: DARKBLUE })
  );
  bar.position.set(tPos.x - 0.6 - k*0.11, tPos.y - 0.45, 0.01);
  scene.add(bar);
  embBars.push(bar);
}

function computeEmbedding(t){
  const d = 8;
  const out = [];
  for (let k=0;k<d;k++){
    const denom = Math.pow(10000, (2*Math.floor(k/2))/d);
    const v = (k % 2 === 0) ? Math.sin(t/denom) : Math.cos(t/denom);
    out.push(v);
  }
  return out;
}

function updateEmbeddingVis(t){
  const emb = computeEmbedding(t);
  for (let k=0;k<embBars.length;k++){
    const v = emb[k];
    const mag = Math.abs(v);
    embBars[k].scale.y = 0.3 + mag*1.3;
    const col = new THREE.Color();
    if (v >= 0) col.setRGB(0.75, 0.35 + 0.2*(1-mag), 0.2);
    else col.setRGB(0.2, 0.35, 0.65);
    embBars[k].material.color.copy(col);
  }
}

// ---------- state & highlighting ----------
const flowStates = ['input','e256','e128','e64','e32','e16','b8','d16','d32','d64','d128','d256','output'];
const state = { flowStep: 'input', t: 500, inspectAttention: false };

function setHighlight(){
  const activeIdx = flowStates.indexOf(state.flowStep);
  for (let i=0;i<flowStates.length;i++){
    const it = blocks[flowStates[i]];
    if (!it) continue;
    const mats = it.mesh.material;
    const isActive = i === activeIdx;
    const isBefore = i < activeIdx;
    for (let mi=0; mi<mats.length; mi++){
      const m = mats[mi];
      if (!m) continue;
      if ((mi === 4) && (it.spec.isImage || it.spec.isNoise)) continue;
      const base = (mi === 2 || mi === 4) ? ORANGE : ORANGE_DARK;
      let c = new THREE.Color(base);
      if (isActive) c.lerp(new THREE.Color(0xffcc66), 0.55);
      else if (!isBefore) c.multiplyScalar(0.6);
      m.color.copy(c);
    }
  }
  for (const a of chainArrows){
    const iTo = flowStates.indexOf(a.userData.toId);
    const base = new THREE.Color(a.userData.baseColor);
    if (iTo === activeIdx) base.lerp(new THREE.Color(0xffcc66), 0.6);
    else if (iTo > activeIdx) base.multiplyScalar(0.6);
    a.userData.material.color.copy(base);
  }
  for (const [pairKey, arc] of Object.entries(skipArcs)){
    const [,decId] = pairKey.split('>');
    let c = new THREE.Color(SKIP);
    if (state.flowStep === decId) c.lerp(new THREE.Color(0xffff66), 0.55);
    arc.userData.material.color.copy(c);
  }
  const showAttn = state.inspectAttention && (state.flowStep === 'e16' || state.flowStep === 'd16');
  attnGroup.visible = showAttn;
  attnCaption.style.display = showAttn ? '' : 'none';
}

// ---------- UI wiring ----------
const btnStep = document.getElementById('btnStep');
const btnPlay = document.getElementById('btnPlay');
const slT = document.getElementById('slT');
const tVal = document.getElementById('tVal');
const chkAttn = document.getElementById('chkAttn');
const stepInfo = document.getElementById('stepInfo');

const stepLabels = {
  input:'input', e256:'enc 256²×128', e128:'enc 128²×128', e64:'enc 64²×256',
  e32:'enc 32²×256', e16:'enc 16²×512 (attn)', b8:'bottleneck 8²×512',
  d16:'dec 16²×512 (attn)', d32:'dec 32²×256', d64:'dec 64²×256',
  d128:'dec 128²×128', d256:'dec 256²×128', output:'output ε̂'
};

btnStep.addEventListener('click', ()=>{
  const cur = flowStates.indexOf(state.flowStep);
  state.flowStep = flowStates[(cur+1) % flowStates.length];
  btnStep.textContent = 'Step: ' + stepLabels[state.flowStep];
  stepInfo.textContent = 'Now at: ' + stepLabels[state.flowStep];
  setHighlight();
});

slT.addEventListener('input', ()=>{
  state.t = parseInt(slT.value, 10);
  tVal.textContent = state.t;
  updateEmbeddingVis(state.t);
});

chkAttn.addEventListener('change', ()=>{
  state.inspectAttention = chkAttn.checked;
  setHighlight();
});

// ---------- demo ----------
const demoSteps = [
  { title:'Input image enters the U-Net', narration:'A 256×256×3 image enters on the left. Timestep t is embedded and injected into every residual block.', state:{flowStep:'input',timestep:500,inspectAttention:false} },
  { title:'Encoder downsampling', narration:'Each encoder stage halves spatial resolution and grows channels: 256→128→64→32→16.', state:{flowStep:'e32',timestep:500,inspectAttention:false} },
  { title:'Self-attention at 16×16', narration:'At 16×16×512 the block uses residual + self-attention (lighter blue arrow). 256 positions attend all-to-all.', state:{flowStep:'e16',timestep:500,inspectAttention:true} },
  { title:'Bottleneck', narration:'The 8×8×512 bottleneck holds the most compressed representation.', state:{flowStep:'b8',timestep:500,inspectAttention:false} },
  { title:'Decoder + skip connections', narration:'Decoder mirrors the encoder. Orange Concatenate arrows splice encoder features back in at each scale.', state:{flowStep:'d64',timestep:500,inspectAttention:false} },
  { title:'Vary the timestep', narration:'Slide t from 0 to 999; the sinusoidal embedding fed into every block updates.', state:{flowStep:'output',timestep:900,inspectAttention:false} },
  { title:'Predicted noise output', narration:'The rightmost slab is the noise prediction ε̂(x_t, t).', state:{flowStep:'output',timestep:500,inspectAttention:false} },
];

let demoIdx = 0, demoPlaying = false, demoTimer = null;

function goToStep(i){
  const s = demoSteps[i];
  state.flowStep = s.state.flowStep;
  state.t = s.state.timestep;
  state.inspectAttention = s.state.inspectAttention;
  slT.value = state.t;
  tVal.textContent = state.t;
  chkAttn.checked = state.inspectAttention;
  btnStep.textContent = 'Step: ' + stepLabels[state.flowStep];
  stepInfo.innerHTML = '<b>'+s.title+'</b><br>'+s.narration;
  updateEmbeddingVis(state.t);
  setHighlight();
}

btnPlay.addEventListener('click', ()=>{
  if (demoPlaying){
    demoPlaying = false;
    clearTimeout(demoTimer);
    btnPlay.textContent = '▶ Play demo';
    return;
  }
  demoPlaying = true;
  btnPlay.textContent = '⏸ Pause demo';
  demoIdx = 0;
  const tick = ()=>{
    if (!demoPlaying) return;
    goToStep(demoIdx);
    demoIdx = (demoIdx+1) % demoSteps.length;
    demoTimer = setTimeout(tick, 2800);
  };
  tick();
});

// ---------- init ----------
updateEmbeddingVis(state.t);
setHighlight();
stepInfo.textContent = 'Click "Step" or "Play demo" to trace activations through the U-Net.';

